<body>
<div class="wrap">
  <h1>Bevásárlólista</h1>
  <p class="hint">Írd be a tételt, válaszd ki a kategóriát, majd kattints a tételre, ha megvetted. A lista automatikusan megmarad.</p>

  <form class="add" id="addForm">
    <label for="itemInput" class="visually-hidden">Új tétel</label>
    <input id="itemInput" type="text" placeholder="Pl. paradicsom" autocomplete="off" maxlength="80">
    <label for="catSelect" class="visually-hidden">Kategória</label>
    <select id="catSelect">
      <option value="zoldseg">Zöldség</option>
      <option value="pekaru">Pékáru</option>
      <option value="tejtermekek">Tejtermék</option>
      <option value="egyeb">Egyéb</option>
    </select>
    <button type="submit" class="add-btn">Hozzáad</button>
  </form>

  <div class="progress" id="progress"></div>
  <div class="bar"><div class="fill" id="fill"></div></div>

  <main id="list" aria-live="polite"></main>
</div>

<script>
const CATS = [
  { id:'zoldseg', label:'Zöldség' },
  { id:'pekaru', label:'Pékáru' },
  { id:'tejtermekek', label:'Tejtermék' },
  { id:'egyeb', label:'Egyéb' }
];
const KEY = 'shopping-list';
const hasStore = !!(window.alfy && window.alfy.storage);
const store = hasStore ? window.alfy.storage : { get:async()=>null, set:async()=>{} };

let items = [];

const $ = id => document.getElementById(id);
const form = $('addForm'), input = $('itemInput'), catSel = $('catSelect');
const listEl = $('list'), progressEl = $('progress'), fillEl = $('fill');

function esc(s){ return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function catLabel(id){ const c = CATS.find(c => c.id === id); return c ? c.label : 'Egyéb'; }

async function load(){
  try {
    const raw = await store.get(KEY);
    if (Array.isArray(raw)) items = raw.filter(it => it && typeof it.name === 'string');
  } catch(e){ items = []; }
  render();
}
async function save(){ try { await store.set(KEY, items); } catch(e){} }

function addItem(name, cat){
  items.push({ id: Date.now() + '_' + Math.random().toString(36).slice(2,7), name, cat, done:false });
  save(); render();
}
function toggle(id){ const it = items.find(i => i.id === id); if(it){ it.done = !it.done; save(); render(); } }
function remove(id){ items = items.filter(i => i.id !== id); save(); render(); }

function render(){
  const total = items.length, done = items.filter(i => i.done).length;
  if (total === 0){
    progressEl.textContent = 'Még nincs tétel a listán.';
    fillEl.style.width = '0%';
    listEl.innerHTML = '<div class="empty-page"><h3>A listád üres</h3><p>Írd be a fenti mezőbe az első tételt, és válaszd ki a kategóriát.</p></div>';
    return;
  }
  progressEl.textContent = `${done} / ${total} megvetve`;
  fillEl.style.width = (total ? Math.round(done/total*100) : 0) + '%';

  let html = '';
  for (const c of CATS){
    const inCat = items.filter(i => i.cat === c.id);
    if (!inCat.length) continue;
    const d = inCat.filter(i => i.done).length;
    html += `<section class="cat"><div class="cat-head"><h2>${esc(c.label)}</h2><span class="count">${d}/${inCat.length}</span></div><ul>`;
    for (const it of inCat){
      html += `<li>
        <button type="button" class="item ${it.done?'done':''}" data-id="${it.id}" aria-pressed="${it.done}" aria-label="${it.done?'Megvettem:':'Megjelölés megvétként:'} ${esc(it.name)}">
          <span class="box" aria-hidden="true"></span><span class="txt">${esc(it.name)}</span>
        </button>
        <button type="button" class="del" data-del="${it.id}" aria-label="Törölve: ${esc(it.name)}">×</button>
      </li>`;
    }
    html += '</ul></section>';
  }
  listEl.innerHTML = html;
}

form.addEventListener('submit', e => {
  e.preventDefault();
  const name = input.value.trim();
  if (!name){ input.focus(); return; }
  addItem(name, catSel.value);
  input.value = '';
  input.focus();
});
listEl.addEventListener('click', e => {
  const t = e.target.closest('[data-id]'), d = e.target.closest('[data-del]');
  if (d){ remove(d.getAttribute('data-del')); }
  else if (t){ toggle(t.getAttribute('data-id')); }
});

load();
</script>
</body>
